// Stryker Trading Academy: /demo-platform (unlisted preview page)
//
// Behaviour for the four Platform-section variations on demo-platform.html
// (markup generated by tools/demo-platform/gen.py from index.html#platform).
//
//   switcher  sticky A/B/C/D chips; the chip of the variation in view lights up
//   A bento   tile tilt + spotlight on fine pointers; tap a tile to open the
//             expand sheet (dialog: Esc, scrim, focus kept inside, focus returned)
//   B story   the step nearest the reading line becomes active and the sticky
//             screen swaps to that tool's screen
//   C orbit   the six tools drift slowly round the hub (one rAF loop, paused
//             off-screen, on hover, and for good after the first tap); tabs
//             with arrow-key support swap the panel
//   D rail    snap rail with arrows, dots and a live count
//
// Motion: transforms/opacity only; every loop stops when its variation is
// off-screen (.dp-off also freezes CSS loops there). prefers-reduced-motion:
// no drift, no tilt, instant swaps.
//
// Depends on: nothing (style.css tokens, demo-platform.css).

(function () {
  'use strict';
  var $ = function (s, r) { return (r || document).querySelector(s); };
  var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var fine = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
  var root = document.documentElement;

  // ------------------------------------------------------------ theme toggle
  var tb = $('#dp-theme');
  if (tb) tb.addEventListener('click', function () {
    var toDay = root.getAttribute('data-theme') !== 'light';
    if (toDay) root.setAttribute('data-theme', 'light'); else root.removeAttribute('data-theme');
    try { localStorage.setItem('stryker_theme', toDay ? 'day' : 'night'); } catch (e) {}
  });

  // ------------------------------------------- visibility of each variation
  var vars = $$('.dp-var');
  var visible = {};
  var chips = $$('.dp-chips a');
  function lightChip() {
    // the variation whose block covers the upper third of the viewport
    var line = window.innerHeight * 0.33, pick = null;
    vars.forEach(function (v) {
      var r = v.getBoundingClientRect();
      if (r.top <= line && r.bottom > line) pick = v.id.slice(4);
    });
    if (!pick) pick = 'A';
    chips.forEach(function (c) { c.classList.toggle('on', c.getAttribute('data-v') === pick); });
  }
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (es) {
      es.forEach(function (en) {
        visible[en.target.id] = en.isIntersecting;
        en.target.classList.toggle('dp-off', !en.isIntersecting);
        if (en.target.id === 'var-C') orbitWake();
      });
    }, { rootMargin: '80px 0px' });
    vars.forEach(function (v) { io.observe(v); });
  } else {
    vars.forEach(function (v) { visible[v.id] = true; });
  }

  // one scroll handler, rAF-throttled, for the switcher and variation B
  var scrollQueued = false;
  function onScroll() {
    if (scrollQueued) return;
    scrollQueued = true;
    requestAnimationFrame(function () {
      scrollQueued = false;
      lightChip();
      if (visible['var-B'] !== false) storyStep();
    });
  }
  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onScroll);

  // ================================================================ A bento
  var tiles = $$('.va-tile[data-k]');
  if (fine && !reduced) {
    tiles.forEach(function (t) {
      var raf = 0, ev = null;
      t.addEventListener('pointermove', function (e) {
        ev = e;
        if (raf) return;
        raf = requestAnimationFrame(function () {
          raf = 0;
          var r = t.getBoundingClientRect();
          var x = (ev.clientX - r.left) / r.width, y = (ev.clientY - r.top) / r.height;
          t.style.setProperty('--mx', (x * 100).toFixed(1) + '%');
          t.style.setProperty('--my', (y * 100).toFixed(1) + '%');
          t.style.setProperty('--ry', ((x - 0.5) * 5).toFixed(2) + 'deg');
          t.style.setProperty('--rx', ((0.5 - y) * 5).toFixed(2) + 'deg');
        });
      });
      t.addEventListener('pointerleave', function () {
        t.style.setProperty('--rx', '0deg'); t.style.setProperty('--ry', '0deg');
      });
    });
  }
  var sheet = $('#va-sheet'), panel = sheet && $('.va-panel', sheet), lastHit = null;
  function openSheet(tile, hit) {
    lastHit = hit;
    $('#va-sheet-k').textContent = $('.va-top .dp-k', tile).textContent;
    $('#va-sheet-title').textContent = $('.va-top h3', tile).textContent;
    var img = $('.va-shot img', tile).cloneNode(true);
    img.removeAttribute('loading');
    var box = $('#va-sheet-img'); box.innerHTML = ''; box.appendChild(img);
    var body = $('#va-sheet-body'); body.innerHTML = '';
    $$('.va-more > *', tile).forEach(function (n) { body.appendChild(n.cloneNode(true)); });
    sheet.hidden = false;
    document.body.style.overflow = 'hidden';
    requestAnimationFrame(function () { sheet.classList.add('open'); panel.focus(); });
  }
  function closeSheet() {
    if (!sheet || sheet.hidden) return;
    sheet.classList.remove('open');
    document.body.style.overflow = '';
    setTimeout(function () { sheet.hidden = true; }, reduced ? 0 : 300);
    if (lastHit) lastHit.focus();
  }
  tiles.forEach(function (t) {
    var hit = $('.va-hit', t);
    hit.addEventListener('click', function () { openSheet(t, hit); });
  });
  if (sheet) {
    $$('[data-close]', sheet).forEach(function (b) { b.addEventListener('click', closeSheet); });
    document.addEventListener('keydown', function (e) {
      if (sheet.hidden) return;
      if (e.key === 'Escape') { closeSheet(); return; }
      if (e.key === 'Tab') {
        var f = $$('a[href], button', panel);
        if (!f.length) return;
        var first = f[0], last = f[f.length - 1];
        if (e.shiftKey && (document.activeElement === first || document.activeElement === panel)) { e.preventDefault(); last.focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
      }
    });
  }

  // ================================================================ B story
  var steps = $$('.vb-step'), screens = $$('.vb-scr'), bars = $$('.vb-rail i'), pathEl = $('#vb-path');
  var curStep = 0;
  function storyStep() {
    if (!steps.length) return;
    var stick = $('.vb-stick'), sr = stick.getBoundingClientRect();
    // reading line: just under the sticky screen on phones, mid-viewport on desktop
    var line = window.innerWidth < 900 ? sr.bottom + 60 : window.innerHeight * 0.5;
    var best = 0, bestD = Infinity;
    steps.forEach(function (s, i) {
      var r = s.getBoundingClientRect();
      var d = r.top <= line && r.bottom >= line ? 0 : Math.min(Math.abs(r.top - line), Math.abs(r.bottom - line));
      if (d < bestD) { bestD = d; best = i; }
    });
    if (best === curStep) return;
    curStep = best;
    steps.forEach(function (s, i) { s.classList.toggle('on', i === best); });
    screens.forEach(function (s, i) {
      if (i === best) { var im = $('img', s); if (im) im.loading = 'eager'; }
      s.classList.toggle('on', i === best);
    });
    bars.forEach(function (b, i) { b.classList.toggle('on', i === best); b.classList.toggle('done', i < best); });
    if (pathEl) pathEl.textContent = $('.dp-go', steps[best]).getAttribute('href');
  }
  // warm the next screens once B is near, so swaps never show an empty frame
  screens.forEach(function (s) { var im = $('img', s); if (im) im.loading = 'eager'; });

  // ================================================================ C orbit
  var stage = $('.vc-stage'), nodes = $$('.vc-node'), panes = $$('.vc-pane'), spokes = $('.vc-spokes');
  var rot = 0, drift = !reduced, hover = false, orbitRaf = 0, lastT = 0;
  if (spokes) {
    var ns = 'http://www.w3.org/2000/svg';
    nodes.forEach(function (n, i) {
      var a = (i * 60 - 90) * Math.PI / 180;
      var l = document.createElementNS(ns, 'line');
      l.setAttribute('x1', (Math.cos(a) * 18).toFixed(2)); l.setAttribute('y1', (Math.sin(a) * 18).toFixed(2));
      l.setAttribute('x2', (Math.cos(a) * 68).toFixed(2)); l.setAttribute('y2', (Math.sin(a) * 68).toFixed(2));
      if (i === 0) l.setAttribute('class', 'on');
      spokes.appendChild(l);
    });
  }
  var spokeLines = spokes ? $$('line', spokes) : [];
  function selectNode(i, focus) {
    nodes.forEach(function (n, j) {
      n.classList.toggle('on', j === i);
      n.setAttribute('aria-selected', j === i ? 'true' : 'false');
      n.tabIndex = j === i ? 0 : -1;
    });
    spokeLines.forEach(function (l, j) { l.setAttribute('class', j === i ? 'on' : ''); });
    panes.forEach(function (p, j) {
      var on = j === i;
      p.hidden = !on;
      p.classList.toggle('on', on);
      p.classList.remove('enter');
      if (on && !reduced) { void p.offsetWidth; p.classList.add('enter'); }
    });
    if (focus) nodes[i].focus();
  }
  nodes.forEach(function (n, i) {
    n.tabIndex = i === 0 ? 0 : -1;
    n.addEventListener('click', function () { drift = false; selectNode(i); });
    n.addEventListener('keydown', function (e) {
      var k = e.key, j = -1;
      if (k === 'ArrowRight' || k === 'ArrowDown') j = (i + 1) % nodes.length;
      else if (k === 'ArrowLeft' || k === 'ArrowUp') j = (i + nodes.length - 1) % nodes.length;
      else if (k === 'Home') j = 0; else if (k === 'End') j = nodes.length - 1;
      if (j < 0) return;
      e.preventDefault(); drift = false; selectNode(j, true);
    });
  });
  if (stage) {
    stage.addEventListener('pointerenter', function () { hover = true; });
    stage.addEventListener('pointerleave', function () { hover = false; orbitWake(); });
  }
  function orbitTick(t) {
    orbitRaf = 0;
    if (!drift || hover || visible['var-C'] === false || document.hidden) { lastT = 0; return; }
    if (lastT) rot = (rot + (t - lastT) * 0.004) % 360;   // ~4 degrees a second
    lastT = t;
    stage.style.setProperty('--rot', rot.toFixed(2) + 'deg');
    orbitRaf = requestAnimationFrame(orbitTick);
  }
  function orbitWake() {
    if (stage && drift && !orbitRaf) orbitRaf = requestAnimationFrame(orbitTick);
  }
  document.addEventListener('visibilitychange', orbitWake);
  orbitWake();

  // ================================================================= D rail
  var rail = $('.vd-rail'), cards = $$('.vd-card'), dots = $$('.vd-dots button');
  var prev = $('.vd-prev'), next = $('.vd-next'), cur = $('#vd-cur');
  function cardStep() { return cards.length > 1 ? cards[1].offsetLeft - cards[0].offsetLeft : rail.clientWidth; }
  function railIndex() { return Math.round(rail.scrollLeft / cardStep()); }
  function goCard(i) {
    i = Math.max(0, Math.min(cards.length - 1, i));
    var max = rail.scrollWidth - rail.clientWidth;
    rail.scrollTo({ left: Math.min(max, i * cardStep()), behavior: reduced ? 'auto' : 'smooth' });
  }
  function railUpdate() {
    var max = rail.scrollWidth - rail.clientWidth;
    var atEnd = rail.scrollLeft >= max - 4;
    var i = atEnd ? cards.length - 1 : railIndex();
    dots.forEach(function (d, j) { d.classList.toggle('on', j === i); });
    if (cur) cur.textContent = ('0' + (i + 1)).slice(-2);
    prev.disabled = rail.scrollLeft <= 4;
    next.disabled = atEnd;
    rail.classList.toggle('at-end', atEnd);
  }
  if (rail) {
    var railQ = false;
    rail.addEventListener('scroll', function () {
      if (railQ) return; railQ = true;
      requestAnimationFrame(function () { railQ = false; railUpdate(); });
    }, { passive: true });
    prev.addEventListener('click', function () { goCard(railIndex() - 1); });
    next.addEventListener('click', function () { goCard(railIndex() + 1); });
    dots.forEach(function (d, j) { d.addEventListener('click', function () { goCard(j); }); });
    rail.addEventListener('keydown', function (e) {
      if (e.target !== rail) return;
      if (e.key === 'ArrowRight') { e.preventDefault(); goCard(railIndex() + 1); }
      if (e.key === 'ArrowLeft') { e.preventDefault(); goCard(railIndex() - 1); }
    });
    window.addEventListener('resize', railUpdate);
    railUpdate();
  }

  onScroll();
})();
